def game_score(points: str) -> str:
    a_points = 0
    b_points = 0

    for point in points:
        # Check if someone already won
        if a_points >= 4 or b_points >= 4:
            break

        # Award the point
        if point == 'A':
            a_points += 1
        elif point == 'B':
            b_points += 1

    # Check for game winner (need at least 4 points and 2+ point lead)
    if a_points >= 4 and a_points > b_points:
        return "Game A"
    if b_points >= 4 and b_points > a_points:
        return "Game B"

    # Convert points to tennis score
    score_map = {0: '0', 1: '15', 2: '30', 3: '40'}

    # Handle deuce and beyond
    if a_points >= 3 and b_points >= 3:
        # At deuce (40-40) or beyond
        if a_points == b_points:
            return "40-40"
        elif a_points > b_points:
            # A is ahead in deuce
            return "Game A"
        else:
            # B is ahead in deuce
            return "Game B"

    # Regular scoring (before deuce)
    a_score = score_map.get(a_points, '40')
    b_score = score_map.get(b_points, '40')

    return f"{a_score}-{b_score}"
